function stem(w){if(w.length>4&&w.slice(-3)==='ing')return w.slice(0,-3);if(w.length>3&&w.slice(-2)==='ed')return w.slice(0,-2);if(w.length>3&&w.slice(-1)==='s')return w.slice(0,-1);return w;}
function words(t){var out=[],seen={};normalizeClaim(t).split(' ').forEach(function(w){if(w.length<3||STOP[w])return;var s=stem(w);if(seen[s])return;seen[s]=1;out.push(s);});return out;}
